package com.example.digitai;

import android.util.Base64;

public final class DigitModel {
    private static final int PROTO_COUNT = 30;
    private static final int FEATURES = 64;
    private static final String MODEL_B64 = "";
    private static final String LABELS = "000111222333444555666777888999";
    private static final byte[] PROTOS = Base64.decode(MODEL_B64, Base64.DEFAULT);

    private DigitModel() {}

    public static int predict(float[] input) {
        double best = Double.MAX_VALUE;
        int bestIndex = 0;

        for (int p = 0; p < PROTO_COUNT; p++) {
            double d = 0.0;
            int base = p * FEATURES;
            for (int i = 0; i < FEATURES; i++) {
                double diff = input[i] * 255.0 - (PROTOS[base + i] & 0xff);
                d += diff * diff;
            }
            if (d < best) {
                best = d;
                bestIndex = p;
            }
        }
        return LABELS.charAt(bestIndex) - '0';
    }
}
